'use strict';
const SupportCore={
 ensure(db){db.supportTickets??=[];return db.supportTickets},
 owns(db,t){return t.owner===MarketCore.accountId(db)},
 visible(db){return this.ensure(db).filter(t=>db.role==='admin'||this.owns(db,t))},
 get(db,id){const t=this.ensure(db).find(t=>t.id===id);if(!t||(db.role!=='admin'&&!this.owns(db,t)))throw Error('문의 접근 권한이 없습니다.');return t},
 create(db,v){const title=String(v.title||'').trim(),body=String(v.body||'').trim();if(!title||title.length>80||!body||body.length>2000)throw Error('제목과 내용을 입력해 주세요.');const categories=['주문·배송','취소·환불','기부·영수증','기관 참여','계정·이용','기타'];if(!categories.includes(v.category))throw Error('문의 유형을 확인해 주세요.');if(v.order&&!db.orders.some(o=>o.id===v.order&&AccountCore.owns(db,o)))throw Error('본인의 주문을 선택해 주세요.');const now=new Date().toISOString(),t={id:MarketCore.uid('CS'),owner:MarketCore.accountId(db),name:db.profile.name||'방문 고객',category:v.category,order:v.order||'',title,status:'접수',priority:'보통',createdAt:now,updatedAt:now,messages:[{body,at:now,staff:false,internal:false}]};this.ensure(db).unshift(t);return t},
 reply(db,id,body,internal=false){const t=this.get(db,id),text=String(body||'').trim();if(!text||text.length>2000)throw Error('상담 내용을 1~2000자로 입력해 주세요.');if(internal&&db.role!=='admin')throw Error('담당자 전용 기능입니다.');if(t.status==='종료')throw Error('종료된 문의는 다시 열어 주세요.');const now=new Date().toISOString();t.messages.push({body:text,staff:db.role==='admin',internal,at:now});t.updatedAt=now;if(!internal)t.status=db.role==='admin'?'답변 완료':'접수';return t},
 state(db,id,status){const t=this.get(db,id);if(!['접수','상담 중','답변 완료','종료'].includes(status))throw Error('처리 상태를 확인해 주세요.');if(db.role!=='admin'&&!['접수','종료'].includes(status))throw Error('담당자 전용 기능입니다.');t.status=status;t.updatedAt=new Date().toISOString();return t}
};
let supportView='write',supportFilter='전체',supportQuery='';
const supportDate=at=>new Date(at).toLocaleString('ko-KR');
const supportCategories=['주문·배송','취소·환불','기부·영수증','기관 참여','계정·이용','기타'];
const supportFAQs=[['배송 상황은 어디에서 확인하나요?','마이 → 구매 내역에서 기관별 주문 상태와 배송 정보를 확인할 수 있어요.'],['반품·환불을 요청하고 싶어요.','구매 내역의 주문 상세에서 취소·교환·반품을 신청해 주세요. 추가 도움이 필요하면 주문번호와 함께 문의를 남겨 주세요.'],['기부금 영수증은 누가 발급하나요?','현물을 수령한 기관이 증빙을 검토하고 발급합니다. 기부 내역에서 진행 상황을 확인해 주세요.'],['기관 쇼핑몰을 운영하고 싶어요.','기관 참여 유형으로 문의해 주세요. 담당자가 기관 정보와 운영 절차를 안내합니다.']];
function supportForm(){return `<form id="support-create-form" class="form-box"><label class="field">문의 유형<select name="category">${supportCategories.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">관련 주문 (선택)<select name="order"><option value="">주문 선택 안 함</option>${db.orders.filter(o=>AccountCore.owns(db,o)).map(o=>`<option value="${esc(o.id)}">${esc(o.id)}</option>`).join('')}</select></label><label class="field">제목<input name="title" maxlength="80" required placeholder="어떤 도움이 필요하세요?"></label><label class="field">내용<textarea name="body" rows="7" required maxlength="2000" placeholder="궁금한 내용을 자세히 알려 주세요. 비밀번호·결제 정보는 입력하지 마세요."></textarea></label><button class="primary-btn green full">문의 접수하기</button><p class="small muted">이 브라우저에 저장되는 상담 체험입니다. 실제 상담원에게 전송되지는 않습니다.</p></form>`}
function supportList(admin=false){const all=SupportCore.visible(db),rows=all.filter(t=>(supportFilter==='전체'||t.status===supportFilter)&&(!supportQuery||[t.id,t.title,t.name,t.category,t.order].join(' ').toLowerCase().includes(supportQuery.toLowerCase())));return `${admin?`<div class="stat-grid">${statCard('미답변 문의',all.filter(t=>['접수','상담 중'].includes(t.status)).length+'건','고객의 이야기를 확인해 주세요',true)}${statCard('24시간 이상 대기',all.filter(t=>['접수','상담 중'].includes(t.status)&&Date.now()-Date.parse(t.updatedAt)>86400000).length+'건','접수·고객 추가 메시지 기준')}${statCard('답변 완료',all.filter(t=>t.status==='답변 완료').length+'건','고객 확인 대기')}${statCard('종료 문의',all.filter(t=>t.status==='종료').length+'건','완료된 상담')}</div>`:''}<form id="support-search" class="buyer-search"><input name="query" value="${esc(supportQuery)}" aria-label="문의 검색" placeholder="문의번호·제목${admin?'·고객명':''} 검색"><select name="status" aria-label="문의 상태">${['전체','접수','상담 중','답변 완료','종료'].map(x=>`<option ${x===supportFilter?'selected':''}>${x}</option>`).join('')}</select><button class="secondary-btn">검색</button></form>${rows.map(t=>`<button class="support-ticket" data-action="support-open" data-id="${esc(t.id)}"><div class="split-row"><small>${esc(t.category)} · ${esc(t.id)}</small>${status(t.status)}</div><strong>${esc(t.title)}</strong><small>${admin?esc(t.name)+' · ':''}${esc(supportDate(t.updatedAt))}${t.order?' · '+esc(t.order):''}${admin?' · 우선순위 '+esc(t.priority):''}</small><p>${esc(t.messages.filter(m=>!m.internal).at(-1)?.body.slice(0,100)||'')}</p></button>`).join('')||empty('표시할 문의가 없어요','문의하기에서 궁금한 점을 남겨 주세요.')}`}
function supportPage(){return header()+`<div class="support-intro"><div class="eyebrow">WE ARE HERE FOR YOU</div><h1>무엇을 도와드릴까요?</h1><p>작은 궁금함도 편하게 이야기해 주세요.<br>운영 시간 ${esc(db.settings.support||'평일 10:00–18:00')}</p></div><section class="section"><nav class="support-tabs">${[['write','문의하기'],['history','내 상담 내역'],['faq','자주 묻는 질문']].map(([v,l])=>btn('support-tab',l,supportView===v?'active':'',`data-tab="${v}"`)).join('')}</nav>${supportView==='write'?supportForm():supportView==='history'?supportList():`<div class="support-faq">${supportFAQs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}</section>`+bottomNav()}
function supportOpen(id){try{const t=SupportCore.get(db,id),admin=db.role==='admin';openModal('상담 내역 · '+t.id,`<div class="split-row"><strong>${esc(t.title)}</strong>${status(t.status)}</div><p class="small muted">${esc(t.category)}${t.order?' · '+esc(t.order):''} · ${esc(t.name)}</p><div class="support-thread">${t.messages.filter(m=>admin||!m.internal).map(m=>`<div class="support-message ${m.staff?'staff':''}"><small>${m.internal?'담당자 내부 메모':m.staff?'방긋 상담팀':esc(t.name)} · ${esc(supportDate(m.at))}</small>${esc(m.body)}</div>`).join('')}</div>${admin?`<label class="field">우선순위<select data-support-priority="${esc(t.id)}">${['낮음','보통','높음','긴급'].map(p=>`<option ${t.priority===p?'selected':''}>${p}</option>`).join('')}</select></label>`:''}<div class="support-status-row">${(admin?['접수','상담 중','답변 완료','종료']:t.status==='종료'?['접수']:['종료']).map(s=>btn('support-state',s==='접수'&&t.status==='종료'?'다시 열기':s,'',`data-id="${esc(t.id)}" data-status="${s}"`)).join('')}</div>${t.status!=='종료'?`<form id="support-reply" data-id="${esc(t.id)}">${admin?`<label class="field">답변 템플릿<select id="support-template"><option value="">직접 작성</option><option>안녕하세요, 방긋마켓입니다. 문의 내용을 확인하고 있으며, 확인 후 안내해 드리겠습니다.</option><option>주문 상세에서 배송 정보를 확인해 주세요. 추가 확인이 필요하시면 주문번호와 문의 내용을 남겨 주세요.</option><option>이용에 불편을 드려 죄송합니다. 문의 내용을 담당 부서에 전달하여 확인 중입니다.</option></select></label>`:''}<label class="field">${admin?'답변 작성':'추가 메시지'}<textarea name="body" rows="4" maxlength="2000" required></textarea></label>${admin?'<label class="check-line"><input type="checkbox" name="internal"> 담당자 내부 메모 (고객에게 숨김)</label>':''}<button class="primary-btn green full">${admin?'답변·메모 저장':'추가 메시지 보내기'}</button></form>`:'<p class="small muted">상담이 종료되었습니다. 추가 질문은 다시 열기를 눌러 남겨 주세요.</p>'}<p class="small muted">브라우저 내 상담 체험 · 실제 상담 전송 미연결</p>`,true)}catch(e){toast(e.message)}}
function initSupport(){
 SupportCore.ensure(db);menus.admin.splice(menus.admin.findIndex(x=>x[0]==='customers'),0,['support','문의·상담 관리']);
 actions.contact=()=>{supportView='write';location.hash='/support';if(currentRoute==='/support')render(true)};
 actions['support-tab']=el=>{supportView=el.dataset.tab;supportFilter='전체';supportQuery='';render()};
 actions['support-open']=el=>supportOpen(el.dataset.id);
 actions['support-state']=el=>{try{SupportCore.state(db,el.dataset.id,el.dataset.status);save();render();supportOpen(el.dataset.id)}catch(e){toast(e.message)}};
 const oldContent=consoleContent;consoleContent=function(){return consoleSection==='support'&&db.role==='admin'?consoleTitle('문의·상담 관리','플랫폼 이용 문의를 접수부터 답변·종료까지 관리합니다. 상품 문의는 고객 문의 메뉴에서 확인하세요.')+supportList(true):oldContent()};
 const oldRender=render;render=function(reset=false){if(route()==='/support'){currentRoute='/support';$('#app').innerHTML=supportPage();rail();document.body.classList.remove('institution-view');document.title='문의하기 · 방긋마켓';applyAppearance()}else oldRender(reset);const menu=$('#desktop-menu');menu.insertAdjacentHTML('beforeend',`<button data-action="contact" class="rail-item rail-contact">${icon('info')}<span>문의하기</span></button>`);if(!$('#app .support-mobile-link')&&!$('#app .console-menu'))$('#app').insertAdjacentHTML('beforeend','<div class="support-mobile-link" style="padding:16px 24px 90px;text-align:center"><button data-action="contact" class="secondary-btn">문의하기 · 내 상담 내역</button></div>')};
 document.addEventListener('submit',e=>{const f=e.target;if(!['support-create-form','support-reply','support-search'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();try{const v=Object.fromEntries(new FormData(f));if(f.id==='support-create-form'){const t=SupportCore.create(db,v);save();supportView='history';render();supportOpen(t.id);toast('문의를 접수했습니다.')}else if(f.id==='support-reply'){SupportCore.reply(db,f.dataset.id,v.body,!!v.internal);save();render();supportOpen(f.dataset.id)}else{supportQuery=String(v.query||'').trim();supportFilter=v.status;render()}}catch(err){toast(err.message)}},true);
 document.addEventListener('change',e=>{if(e.target.id==='support-template'){const box=$('#support-reply textarea');if(box&&e.target.value)box.value=e.target.value}if(e.target.dataset.supportPriority&&db.role==='admin'){const t=SupportCore.get(db,e.target.dataset.supportPriority);if(['낮음','보통','높음','긴급'].includes(e.target.value)){t.priority=e.target.value;save();toast('우선순위를 저장했습니다.')}}});
}
